<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\BannedWord;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class BannedWordController extends Controller
{public function index(){return view('admin.banned-words.index',['words'=>BannedWord::orderBy('word')->paginate(30)]);}public function store(Request $r){BannedWord::create($this->data($r));return back()->with('success','Đã thêm từ cấm.');}public function update(Request $r,BannedWord $word){$word->update($this->data($r,$word));return back()->with('success','Đã cập nhật.');}public function toggle(BannedWord $word){$word->update(['status'=>$word->status==='active'?'inactive':'active']);return back();}public function destroy(BannedWord $word){$word->delete();return back()->with('success','Đã xóa.');}private function data(Request $r,?BannedWord $word=null):array{return $r->validate(['word'=>['required','string','max:191',Rule::unique('banned_words')->ignore($word)],'status'=>'required|in:active,inactive']);}}
